package vn.iotstar.example1.repository; import java.util.Optional; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import vn.iotstar.example1.entity.User; public interface UserRepository extends JpaRepository<User,Long>{ boolean existsByEmailIgnoreCase(String email); Optional<User> findByEmailIgnoreCase(String email); @Query("select u from User u join fetch u.role where lower(u.email)=lower(:email)") Optional<User> findByEmailWithRole(@Param("email") String email); }
